"""French printable report using the same application state and export route."""
import html
from business_fr import describe, STATUS, DECISIONS, SOURCE_TITLES, LIMITS
def export_data(state):
    from guardian import EXCERPTS
    def decision(r):return dict(date=r['time'],decision=DECISIONS[r['decision']],proposition=r['wording'],note=r['note']) if r else None
    problems=[]
    for f in state['findings']:
        d=describe(f)
        problems.append(dict(titre=d['name'],statut=d['status'],priorite=d['severity'],explication=d['explanation'],impact_client=d['impact'],explications_possibles=d['alternatives'],action_recommandee=d['action'],proposition=d['suggestion'],decision=decision(f['review']),cas_historique=f.get('historical',False),comparaison_des_roles=[dict(point=r['theme'],description_du_guide=r['article'],conditions_et_faq=r['terms']) for r in f.get('context',[])],preuves=[dict(citation=EXCERPTS[q]['quote'],url=EXCERPTS[q]['url'],langue='anglais' if EXCERPTS[q]['source']=='english' else 'français',date_observation=EXCERPTS[q]['observed'],historique=EXCERPTS[q]['historical']) for q in f['evidence']]+[dict(citation=c['evidence'],url=c['source_url'],langue='français',date_observation=c['observed'],historique=False,verification=c['verification_note'],presence_actuelle_verifiee=c['verification']=='fresh_index') for c in f.get('proofs',[])]))
    return dict(date_audit=state['sources']['audit_date'],type_audit='Revue locale d’extraits publics sélectionnés',problemes=problems,
      historique_modifications=[dict(date=h['time'],revision=h['revision'],avant=h['before']['text'],apres=h['after']['text'],statut_avant=STATUS[h['before_status']],statut_apres=STATUS[h['after_status']],simulation_locale=True) for h in state['history']],
      historique_informations=[dict(date=h['time'],titre=h['after']['title'],valeur_precedente=h['before']['value'] if h['before'] else 'Nouvelle saisie',valeur=h['after']['value'],extrait_fourni=h['after']['excerpt'],url_declaree_non_verifiee=h['after']['source_url'],exemple_fictif=h['after']['simulated'],statut=STATUS[h['status']]) for h in state.get('information_history',[])],
      decisions=[decision(r) for r in state['reviews']],graphe_impact=__import__('impact_report_fr').export(state.get('impact',{})),limites=LIMITS)

def context_table(f,e):
    if not f.get('context'):return ''
    return '<div class="role-comparison"><h4>Quel modèle s’applique au service réservé ?</h4><table><thead><tr><th>Point à distinguer</th><th>Description du guide</th><th>Conditions et FAQ de MénageSimple</th></tr></thead><tbody>'+''.join(f'<tr><th>{e(r["theme"])}</th><td>{e(r["article"])}</td><td>{e(r["terms"])}</td></tr>' for r in f['context'])+'</tbody></table><p>Une gestion déléguée ne suffit pas à établir un changement d’employeur. Ce constat reste à clarifier, même après une décision de revue.</p></div>'
def render(state):
    from guardian import EXCERPTS, now
    e=lambda v:html.escape(str(v),quote=True)
    findings=sorted(state['findings'],key=lambda f:{'cancellation':0,'employer':1,'reference':2,'equipment':3}.get(f['id'],4));counts={k:sum(f['status'] in v and not (k=='écarts actuels à examiner' and f.get('historical')) for f in findings) for k,v in {'écarts actuels à examiner':('Wording inconsistency','Potential mismatch'),'points à clarifier':('Clarity concern','Insufficient evidence'),'résolutions locales simulées':('Resolved in simulation',),'contrôles compatibles':('Compatible input',)}.items()}
    blocks=[]
    for f in findings:
        d=describe(f);review=f['review'];source=''
        if f.get('submitted'):
            s=f['submitted'];source=f'<aside><b>{"Exemple fictif saisi" if s["simulated"] else "Information déclarée par le réviseur"}</b><p>{e(s["excerpt"])}</p><p>Valeur structurée : {e(s["value"])}. URL non vérifiée : <a href="{e(s["source_url"])}">{e(s["source_url"])}</a></p></aside>'
        quotes=''.join(f'<blockquote>{e(EXCERPTS[q]["quote"])}<br><a href="{e(EXCERPTS[q]["url"])}">{e(EXCERPTS[q]["url"])}</a><br><small>{"Anglais" if EXCERPTS[q]["source"]=="english" else "Français"} · observation : {e(EXCERPTS[q]["observed"])} · {"historique" if EXCERPTS[q]["historical"] else "lecture directe vérifiée"}<br>Périmètre : {e(next(s["scope"] for s in state["sources"]["sources"] if s["id"]==EXCERPTS[q]["source"]))}</small></blockquote>' for q in f['evidence'])
        quotes+=''.join('<blockquote><b>'+e('Conditions générales' if c['id']=='PAY-CGV' else 'Page de '+c.get('region',''))+'</b><p>'+e('Citation vérifiée' if c['verification']=='fresh_index' else 'Ancien extrait non authentifié — présence actuelle non vérifiée')+'</p>'+e(c['evidence'])+'<br><a href="'+e(c['source_url'])+'">'+e(c['source_url'])+'</a><p>'+e(c['verification_note'])+'</p></blockquote>' for c in f.get('proofs',[]))
        source+=context_table(f,e)
        blocks.append(f'<section><h2>{e(d["name"])}</h2><p class="badge">{e(d["status"])} · Priorité {e(d["severity"].lower())}</p>{source}{quotes}<p>{e(d["explanation"])}</p><h3>Conséquence possible pour le client</h3><p>{e(d["impact"])}</p><h3>À confirmer avant d’agir</h3><p>{e(d["alternatives"])}</p><h3>Prochaine action</h3><p>{e(d["action"])}</p><h3>Proposition de clarification ou correction, à confirmer</h3><p>{e(review["wording"] if review else d["suggestion"])}</p><p><b>Décision du réviseur :</b> {e(DECISIONS[review["decision"]] if review else "En attente")}</p></section>')
    history=''.join(f'<li>Révision {h["revision"]} · {e(h["time"])}<p>Avant : {e(h["before"]["text"])} — {e(STATUS[h["before_status"]])}</p><p>Après : {e(h["after"]["text"])} — {e(STATUS[h["after_status"]])}</p><p>Service : {"standard" if h["after"]["scope"]=="regular" else "autre"} ; conditions concordantes supposées : {"oui" if h["after"]["confirmed"] else "non"}.</p></li>' for h in state['history'])
    inputs=''.join(f'<li>{e(h["time"])} · {e(h["after"]["title"])} · {e(STATUS[h["status"]])}<p>Valeur précédente : {e(h["before"]["value"] if h["before"] else "nouvelle saisie")} ; nouvelle valeur : {e(h["after"]["value"])}</p><p>{"Simulation fictive" if h["after"]["simulated"] else "Information fournie par le réviseur"} · URL déclarée, non vérifiée.</p></li>' for h in state.get('information_history',[]))
    reviews=''.join(f'<li>{e(r["time"])} · {e(DECISIONS[r["decision"]])}<p>{e(r["wording"])}</p><p>Note : {e(r["note"])}</p><small>Version examinée : {e(r["fingerprint"])}</small></li>' for r in state['reviews'])
    from impact_report_fr import render as render_impact
    graph_section=render_impact(state.get('impact',{}))
    provenance=''.join(f'<li><a href="{e(s["url"])}">{e(SOURCE_TITLES[s["id"]])}</a> · vérification : {e(s["checked_at"])}<p>Version affichée : {"15 juillet 2026" if s["id"]=="terms" else "date d’effet non confirmée"}</p><small>SHA-256 : {e(s["sha256"])}</small></li>' for s in state['sources']['sources'])
    return '<!doctype html><html lang="fr"><meta charset="utf-8"><title>PolicyLens — Rapport MénageSimple</title><style>body{font:15px/1.65 Segoe UI,sans-serif;color:#183c43;max-width:900px;margin:40px auto;padding:20px}h1{font-size:34px}h2{font-size:23px}h3{font-size:15px;margin-bottom:0}section{border-top:1px solid #ccd9d4;margin-top:28px;padding-top:20px}blockquote{border-left:3px solid #167b75;padding:8px 18px;margin:12px 0;background:#f4f8f7}a,small{overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;vertical-align:top;border:1px solid #ccd9d4;padding:9px}th{background:#eef5f3}.summary,aside{padding:18px;background:#eaf4f1}.badge{font-weight:600;color:#186b63}small{font-size:11px}@media print{body{margin:0;font-size:10pt}h2,h3{break-after:avoid}blockquote,aside{break-inside:avoid}}</style><h1>PolicyLens / MénageSimple</h1><p>Rapport de cohérence des informations clients</p><p>Extraits revérifiés le 12 novembre 2026 ; cas tarifaire historique du 9 novembre · Export du '+e(now())+'</p><div class="summary"><h2>Synthèse pour le responsable</h2><p>'+e(' ; '.join(f'{k.capitalize()} : {v}' for k,v in counts.items()))+'.</p><p>Priorité : confirmer la règle d’annulation applicable, harmoniser les textes concernés et vérifier la correction avant publication. Les propositions et modifications restent locales.</p></div>'+graph_section+''.join(blocks)+'<h2>Historique des corrections simulées</h2><p>Copie locale actuelle : '+e(state['snapshot']['text'])+'</p><ol>'+(history or '<li>Aucune modification locale.</li>')+'</ol><h2>Nouvelles informations analysées</h2><ol>'+(inputs or '<li>Aucune saisie supplémentaire.</li>')+'</ol><h2>Historique des décisions humaines</h2><ol>'+(reviews or '<li>Aucune décision enregistrée.</li>')+'</ol><h2>Sources publiques et traçabilité</h2><ul>'+provenance+'</ul><h2>Limites et suite à donner</h2><ul>'+''.join('<li>'+e(t)+'</li>' for t in LIMITS)+'</ul><p>Étape suivante : validation par le responsable métier, puis mise à jour des contenus dans le processus habituel de l’entreprise. Cet outil ne publie aucune correction.</p></html>'
